import{_ as i,o as l,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"CDS Jewel -- Messenger, Priorities for Client","description":"","frontmatter":{"title":"CDS Jewel -- Messenger, Priorities for Client","date":"2015-08-04T00:00:00.000Z","updated":"2015-08-04T00:00:00.000Z","tags":["Ceph","分布式存储","消息优先级","Token Bucket","PD Cream"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Jewel_--_Messenger_Priorities_for_Client.md","filePath":"posts/2015/CDS_Jewel_--_Messenger_Priorities_for_Client.md","lastUpdated":1780459816000}'),o={name:"posts/2015/CDS_Jewel_--_Messenger_Priorities_for_Client.md"};function s(n,e,_,a,p,g){return l(),t("div",null,[...e[0]||(e[0]=[r("<p>本次会议主要讨论了Ceph客户端消息优先级的问题，旨在解决当前Ceph系统中存在的负载不均衡和性能问题。会议内容主要包括以下要点：</p><ol><li><p><strong>议题概述</strong>： 讨论如何通过消息优先级解决客户端负载不均衡和性能瓶颈。</p></li><li><p><strong>讨论的主要议题</strong>：</p><ul><li><strong>当前问题</strong>： 客户端之间负载不均衡，部分客户端响应时间过长；系统存在性能瓶颈。</li><li><strong>解决方案</strong>： 引入简单/优先模型，通过优先级队列来分配负载；优化PD Cream模型，考虑性能问题；调整FL Journal Queen的优先级，提高性能。</li><li><strong>技术方案</strong>： 使用Token Bucket算法控制客户端优先级；修改现有代码实现优先级队列；在文件存储层进行优先级控制。</li></ul></li><li><p><strong>决定的事项</strong>：</p><ul><li>评估Token Bucket算法的适用性，并在现有代码中实现优先级队列。</li><li>优化PD Cream模型，提高性能。</li><li>调整FL Journal Queen的优先级，提高性能。</li><li>探讨在文件存储层进行优先级控制的方案。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>研发团队进一步研究Token Bucket算法，并评估其在Ceph系统中的应用。</li><li>优化PD Cream模型，并进行测试。</li><li>调整FL Journal Queen的优先级，并观察性能变化。</li><li>探索在文件存储层进行优先级控制的方案，并进行可行性分析。</li></ul></li><li><p><strong>其他</strong>：</p><ul><li>讨论了Ceph系统中客户端连接数限制的问题，并提出了可能的解决方案。</li><li>讨论了Ceph系统中资源分配的问题，并提出了可能的优化方案。</li></ul></li></ol>",2)])])}const c=i(o,[["render",s]]);export{C as __pageData,c as default};
